import { test } from "node:test";
import { fail, say } from "../shared/dojo.ts";
import { topK, wordCount } from "./words.ts";

const show = (o: unknown) => JSON.stringify(o);

test("Lv2_Order", () => {
	const got = topK({ a: 1, b: 3, c: 2 }, 3), want = [["b", 3], ["c", 2], ["a", 1]];
	if (show(got) !== show(want)) fail("wrong_order", say(`topK({a:1, b:3, c:2}, 3) 应该是 ${show(want)}，实际是 ${show(got)}。`, `topK({a:1, b:3, c:2}, 3) should be ${show(want)}, got ${show(got)}.`));
});

test("Lv2_Ties", () => {
	const got = topK({ pear: 2, apple: 2, fig: 5, kiwi: 1 }, 3), want = [["fig", 5], ["apple", 2], ["pear", 2]];
	if (got.length > 3) fail("too_many", say(`k = 3 时返回了 ${got.length} 个：${show(got)}。`, `With k = 3 it returned ${got.length}: ${show(got)}.`));
	if (show(got) !== show(want)) fail("tie_order", say(`次数相同的 apple 和 pear 要按字母顺序：期望 ${show(want)}，实际 ${show(got)}。`, `apple and pear have the same count and must be alphabetical: expected ${show(want)}, got ${show(got)}.`));
});

test("Lv2_K", () => {
	const counts = { a: 3, b: 2, c: 1 };
	const two = topK(counts, 2);
	if (two.length > 2) fail("too_many", say(`k = 2 时返回了 ${two.length} 个：${show(two)}。`, `With k = 2 it returned ${two.length}: ${show(two)}.`));
	const all = topK(counts, 10);
	if (all.length !== 3) fail("too_few", say(`k = 10 而只有 3 个词时，应该返回全部 3 个，实际返回 ${all.length} 个：${show(all)}。`, `With k = 10 and only 3 words, all 3 should come back; got ${all.length}: ${show(all)}.`));
	if (show(two) !== show([["a", 3], ["b", 2]])) fail("wrong_order", say(`k = 2 时应该是 [["a",3],["b",2]]，实际是 ${show(two)}。`, `With k = 2 it should be [["a",3],["b",2]], got ${show(two)}.`));
});
